import json, os, signal, sys, time, termios, stat
from pathlib import Path
root = Path(sys.argv[1])
started = time.monotonic()
count = 0

def finish(reason):
    (root / 'finished.json').write_text(json.dumps(dict(reason=reason, elapsed=time.monotonic()-started, heartbeats=count)))
    print('SYNTHETIC_FINISHED '+reason, flush=True)
    raise SystemExit(0)

def cancelled(signum, frame):
    finish('SIGINT' if signum == signal.SIGINT else 'SIGTERM')

signal.signal(signal.SIGINT, cancelled)
signal.signal(signal.SIGTERM, cancelled)
diagnostics = {'requested_tty': True, 'isatty': os.isatty(0), 'character_device': stat.S_ISCHR(os.fstat(0).st_mode)}
for label, operation in [('ttyname', lambda: os.ttyname(0)), ('foreground_group', lambda: os.tcgetpgrp(0)), ('termios', lambda: termios.tcgetattr(0))]:
    try:
        value = operation()
        if label == 'termios':
            value = {'ISIG': bool(value[3] & termios.ISIG), 'ICANON': bool(value[3] & termios.ICANON), 'VINTR': repr(value[6][termios.VINTR])}
        diagnostics[label] = value
    except OSError as exc:
        diagnostics[label] = {'errno': exc.errno, 'error': exc.strerror}
(root / 'terminal.json').write_text(json.dumps(diagnostics))
(root / 'started.json').write_text(json.dumps(dict(pid=os.getpid(), group=os.getpgrp(), tty=os.isatty(0))))
print('SYNTHETIC_STARTED', flush=True)
while time.monotonic()-started < 3:
    count += 1
    (root / 'heartbeat.json').write_text(json.dumps(dict(count=count, elapsed=time.monotonic()-started)))
    time.sleep(.05)
finish('SAFETY_DEADLINE')
